  1→using Six.Automerge.Repository;
  2→using Six.Automerge.Repo.Network.SignalR.Client;
  3→
  4→namespace Six.Automerge.Repo.Network.SignalR;
  5→
  6→/// <summary>
  7→/// SignalR-based network adapter for Automerge document synchronization.
  8→/// </summary>
  9→/// <remarks>
 10→/// This adapter provides real-time collaborative editing over ASP.NET Core SignalR with:
 11→/// <list type="bullet">
 12→///   <item><description>Automatic reconnection and connection lifecycle management</description></item>
 13→///   <item><description>MessagePack serialization with LZ4 compression for bandwidth efficiency</description></item>
 14→///   <item><description>Document-based group subscriptions for targeted message delivery</description></item>
 15→///   <item><description>Thread-safe operations with concurrent access support</description></item>
 16→/// </list>
 17→///
 18→/// <para>
 19→/// <strong>Usage Example:</strong>
 20→/// <code>
 21→/// var adapter = new SignalRNetworkAdapter(connectionService, loggerFactory);
 22→/// adapter.MessageReceived += (sender, args) => {
 23→///   Console.WriteLine($"Received: {args.Message.MessageType}");
 24→/// };
 25→/// adapter.Connect(PeerId.Generate(), null);
 26→/// await adapter.WhenReady();
 27→/// adapter.Send(syncMessage);
 28→/// </code>
 29→/// </para>
 30→/// </remarks>
 31→[PublicAPI]
 32→public sealed class SignalRNetworkAdapter : INetworkAdapter, IDocumentsHubClient, IDisposable, IAsyncDisposable
 33→{
 34→  readonly ISignalRConnectionService _connectionService;
 35→  readonly ILogger<SignalRNetworkAdapter> _logger;
 36→  readonly string _adapterId;
 37→  readonly SemaphoreSlim _lock = new(1, 1);
 38→  readonly TaskCompletionSource _readyTcs = new();
 39→  readonly ConcurrentDictionary<string, byte> _subscribedDocuments = new();
 40→
 41→  HubConnection? _connection;
 42→  PeerId? _peerId;
 43→  bool _isReady;
 44→  bool _disposed;
 45→
 46→  /// <summary>
 47→  /// Initializes a new instance of the <see cref="SignalRNetworkAdapter"/> class.
 48→  /// </summary>
 49→  /// <param name="connectionService">The SignalR connection service.</param>
 50→  /// <param name="loggerFactory">The logger factory.</param>
 51→  public SignalRNetworkAdapter(
 52→    ISignalRConnectionService connectionService,
 53→    ILoggerFactory loggerFactory)
 54→  {
 55→    _connectionService = connectionService ?? throw new ArgumentNullException(nameof(connectionService));
 56→    ArgumentNullException.ThrowIfNull(loggerFactory);
 57→
 58→    _logger = loggerFactory.CreateLogger<SignalRNetworkAdapter>();
 59→    _adapterId = $"signalr-{Guid.NewGuid():N}";
 60→  }
 61→
 62→  /// <inheritdoc />
 63→  public string AdapterId => _adapterId;
 64→
 65→  /// <inheritdoc />
 66→  public bool IsReady => _isReady;
 67→
 68→  /// <inheritdoc />
 69→  public Task WhenReady() => _readyTcs.Task;
 70→
 71→  /// <inheritdoc />
 72→  public event EventHandler<PeerCandidateEventArgs>? PeerCandidate;
 73→
 74→  /// <inheritdoc />
 75→  public event EventHandler<PeerDisconnectedEventArgs>? PeerDisconnected;
 76→
 77→  /// <inheritdoc />
 78→  public event EventHandler<MessageReceivedEventArgs>? MessageReceived;
 79→
 80→  /// <inheritdoc />
 81→  public event EventHandler? Closed;
 82→
 83→  /// <inheritdoc />
 84→  public void Connect(PeerId peerId, PeerMetadata? metadata = null)
 85→  {
 86→    if (_disposed)
 87→      throw new ObjectDisposedException(nameof(SignalRNetworkAdapter));
 88→
 89→    _ = ConnectAsyncInternal(peerId, metadata);
 90→  }
 91→
 92→  async Task ConnectAsyncInternal(PeerId peerId, PeerMetadata? metadata)
 93→  {
 94→    await _lock.WaitAsync();
 95→    try
 96→    {
 97→      if (_isReady)
 98→      {
 99→        _logger.LogWarning("Adapter already connected. Ignoring duplicate Connect call.");
100→        return;
101→      }
102→
103→      _logger.LogInformation("Connecting SignalR adapter for peer: {PeerId}", peerId);
104→      _peerId = peerId;
105→
106→      // Get connection from service
107→      _connection = await _connectionService.GetConnection();
108→      _logger.LogDebug("SignalR connection established. ConnectionId={ConnectionId}", _connection.ConnectionId ?? "<pending>");
109→
110→      // Register client methods for hub callbacks
111→      _logger.LogDebug("Registering hub callbacks for connection {ConnectionId}", _connection.ConnectionId ?? "<pending>");
112→      _connection.On<MessageDto>(
113→        "OnReceiveMessage",
114→        msg =>
115→        {
116→          _logger.LogTrace("Hub invoked OnReceiveMessage. DocumentId={DocumentId}, MessageType={MessageType}, SenderId={SenderId}",
117→            msg.DocumentId,
118→            msg.MessageType,
119→            msg.SenderId);
120→          _ = ((IDocumentsHubClient)this).OnReceiveMessage(msg);
121→        });
122→      _connection.On<PeerHandshakeDto>(
123→        "OnPeerJoined",
124→        handshake =>
125→        {
126→          _logger.LogTrace("Hub invoked OnPeerJoined for PeerId={PeerId}", handshake.PeerId);
127→          _ = ((IDocumentsHubClient)this).OnPeerJoined(handshake);
128→        });
129→      _connection.On<string>(
130→        "OnPeerLeft",
131→        peerId =>
132→        {
133→          _logger.LogTrace("Hub invoked OnPeerLeft for PeerId={PeerId}", peerId);
134→          _ = ((IDocumentsHubClient)this).OnPeerLeft(peerId);
135→        });
136→
137→      // Hook connection lifecycle events
138→      _connection.Closed += OnConnectionClosedAsync;
139→
140→      // Send handshake and receive the server's identity
141→      var handshake = PeerHandshakeDto.Create(peerId, metadata);
142→      var serverHandshake = await _connection.InvokeAsync<PeerHandshakeDto>("Handshake", handshake);
143→
144→      _logger.LogInformation(
145→        "Handshake completed for peer: {PeerId}. Server peer: {ServerPeerId}",
146→        peerId, serverHandshake.PeerId);
147→
148→      // Mark ready
149→      _isReady = true;
150→      _readyTcs.TrySetResult();
151→
152→      // Raise PeerCandidate with the SERVER's PeerId (our direct peer),
153→      // not our own PeerId
154→      var serverPeerId = new PeerId(serverHandshake.PeerId);
155→      var serverMetadata = serverHandshake.Metadata?.ToPeerMetadata();
156→      RaisePeerCandidate(serverPeerId, serverMetadata);
157→    }
158→    catch (Exception ex)
159→    {
160→      _logger.LogError(ex, "Failed to connect SignalR adapter for peer: {PeerId}", peerId);
161→      _readyTcs.TrySetException(ex);
162→      throw;
163→    }
164→    finally
165→    {
166→      _lock.Release();
167→    }
168→  }
169→
170→  /// <inheritdoc />
171→  public void Send(IRepoMessage message)
172→  {
173→    if (_disposed)
174→      throw new ObjectDisposedException(nameof(SignalRNetworkAdapter));
175→
176→    ArgumentNullException.ThrowIfNull(message);
177→
178→    _ = SendAsyncInternal(message);
179→  }
180→
181→  async Task SendAsyncInternal(IRepoMessage message)
182→  {
183→    await _lock.WaitAsync();
184→    try
185→    {
186→      if (!_isReady || _connection is null)
187→      {
188→        _logger.LogWarning("Cannot send message: adapter not ready or connection is null");
189→        return;
190→      }
191→
192→      var documentId = message.DocumentId;
193→
194→      if (documentId is null)
195→      {
196→        _logger.LogWarning("Cannot send message: DocumentId is null or empty");
197→        return;
198→      }
199→
200→      if (_peerId is null)
201→      {
202→        _logger.LogWarning("Cannot send message type {MessageType}: adapter has no peer ID assigned", message.MessageType);
203→        return;
204→      }
205→
206→      // Auto-subscribe to document if not already subscribed
207→      var documentIdValue = documentId.Value;
208→      var documentIdString = documentIdValue.Value;
209→
210→      if (!_subscribedDocuments.ContainsKey(documentIdString))
211→      {
212→        _logger.LogDebug("Auto-subscribing to document: {DocumentId}", documentIdString);
213→        await SubscribeToDocumentInternalAsync(documentIdString);
214→      }
215→
216→      var messageWithSender = EnsureSender(message, _peerId.Value);
217→
218→      if (messageWithSender.SenderId is null && messageWithSender is DocumentSnapshotMessage snapshotWithoutSender)
219→      {
220→        messageWithSender = snapshotWithoutSender with { SenderId = _peerId.Value };
221→      }
222→
223→      _logger.LogInformation(
224→        "Sending {MessageType} message for document {DocumentId} via SignalR connection {ConnectionId} as sender {SenderId}",
225→        messageWithSender.MessageType,
226→        messageWithSender.DocumentId?.Value,
227→        _connection.ConnectionId ?? "<pending>",
228→        messageWithSender.SenderId?.ToString());
229→
230→      // Create MessageDto
231→      var messageData = GetMessageData(messageWithSender);
232→      var messageDto = MessageDto.FromRepoMessage(messageWithSender, messageData!);
233→
234→      // Send to hub
235→      await _connection.InvokeAsync("SendMessage", messageDto);
236→
237→      _logger.LogInformation("Hub accepted {MessageType} message for document {DocumentId} on connection {ConnectionId}",
238→        messageWithSender.MessageType,
239→        messageWithSender.DocumentId?.Value,
240→        _connection.ConnectionId ?? "<pending>");
241→    }
242→    catch (Exception ex)
243→    {
244→      _logger.LogError(ex, "Failed to send message type {MessageType} for document {DocumentId}",
245→        message.MessageType, message.DocumentId?.Value);
246→    }
247→    finally
248→    {
249→      _lock.Release();
250→    }
251→  }
252→
253→  /// <summary>
254→  /// Subscribes to a document to receive sync messages.
255→  /// </summary>
256→  /// <param name="documentId">The document ID to subscribe to.</param>
257→  public async Task SubscribeToDocumentAsync(string documentId)
258→  {
259→    if (_disposed)
260→      throw new ObjectDisposedException(nameof(SignalRNetworkAdapter));
261→
262→    ArgumentException.ThrowIfNullOrEmpty(documentId);
263→
264→    await _lock.WaitAsync();
265→    try
266→    {
267→      await SubscribeToDocumentInternalAsync(documentId);
268→    }
269→    finally
270→    {
271→      _lock.Release();
272→    }
273→  }
274→
275→  async Task SubscribeToDocumentInternalAsync(string documentId)
276→  {
277→    if (_subscribedDocuments.ContainsKey(documentId))
278→    {
279→      _logger.LogDebug("Already subscribed to document: {DocumentId}", documentId);
280→      return;
281→    }
282→
283→    if (_connection is null)
284→    {
285→      _logger.LogWarning("Cannot subscribe: connection is null");
286→      return;
287→    }
288→
289→    await _connection.InvokeAsync("SubscribeToDocument", documentId);
290→    _subscribedDocuments.TryAdd(documentId, 0);
291→
292→    _logger.LogInformation("Subscribed to document: {DocumentId}", documentId);
293→  }
294→
295→  /// <summary>
296→  /// Unsubscribes from a document.
297→  /// </summary>
298→  /// <param name="documentId">The document ID to unsubscribe from.</param>
299→  public async Task UnsubscribeFromDocumentAsync(string documentId)
300→  {
301→    if (_disposed)
302→      throw new ObjectDisposedException(nameof(SignalRNetworkAdapter));
303→
304→    ArgumentException.ThrowIfNullOrEmpty(documentId);
305→
306→    await _lock.WaitAsync();
307→    try
308→    {
309→      await UnsubscribeFromDocumentInternalAsync(documentId);
310→    }
311→    finally
312→    {
313→      _lock.Release();
314→    }
315→  }
316→
317→  async Task UnsubscribeFromDocumentInternalAsync(string documentId)
318→  {
319→    if (!_subscribedDocuments.ContainsKey(documentId))
320→    {
321→      _logger.LogDebug("Not subscribed to document: {DocumentId}", documentId);
322→      return;
323→    }
324→
325→    if (_connection is null)
326→    {
327→      _logger.LogWarning("Cannot unsubscribe: connection is null");
328→      return;
329→    }
330→
331→    await _connection.InvokeAsync("UnsubscribeFromDocument", documentId);
332→    _subscribedDocuments.TryRemove(documentId, out _);
333→
334→    _logger.LogInformation("Unsubscribed from document: {DocumentId}", documentId);
335→  }
336→
337→  /// <inheritdoc />
338→  public async Task Disconnect()
339→  {
340→    if (_disposed)
341→      return;
342→
343→    await _lock.WaitAsync();
344→    try
345→    {
346→      if (!_isReady)
347→        return;
348→
349→      _logger.LogInformation("Disconnecting SignalR adapter for peer: {PeerId}", _peerId);
350→
351→      // Unsubscribe from all documents
352→      var documents = _subscribedDocuments.Keys.ToArray();
353→      foreach (var documentId in documents)
354→      {
355→        await UnsubscribeFromDocumentInternalAsync(documentId);
356→      }
357→
358→      // Stop connection
359→      await _connectionService.Stop();
360→
361→      // Clean up
362→      if (_connection is not null)
363→      {
364→        _connection.Closed -= OnConnectionClosedAsync;
365→        _connection = null;
366→      }
367→
368→      _isReady = false;
369→
370→      // Raise events
371→      if (_peerId is not null)
372→        RaisePeerDisconnected(_peerId.Value);
373→
374→      RaiseClosed();
375→
376→      _logger.LogInformation("Disconnected SignalR adapter for peer: {PeerId}", _peerId);
377→    }
378→    finally
379→    {
380→      _lock.Release();
381→    }
382→  }
383→
384→  /// <inheritdoc />
385→  Task IDocumentsHubClient.OnReceiveMessage(MessageDto messageDto)
386→  {
387→    try
388→    {
389→      _logger.LogInformation("SignalR hub delivered message type {MessageType} for document {DocumentId} from {SenderId}",
390→        messageDto.MessageType, messageDto.DocumentId, messageDto.SenderId);
391→
392→      // Deserialize to IRepoMessage based on MessageType
393→      var message = DeserializeMessage(messageDto);
394→      if (message is null)
395→      {
396→        _logger.LogWarning("Failed to deserialize message type {MessageType}", messageDto.MessageType);
397→        return Task.CompletedTask;
398→      }
399→
400→      // Raise MessageReceived event (deferred to avoid blocking SignalR thread)
401→      _ = Task.Run(() => RaiseMessageReceived(message));
402→    }
403→    catch (Exception ex)
404→    {
405→      _logger.LogError(ex, "Error processing received message type {MessageType}", messageDto.MessageType);
406→    }
407→
408→    return Task.CompletedTask;
409→  }
410→
411→  /// <inheritdoc />
412→  Task IDocumentsHubClient.OnPeerJoined(PeerHandshakeDto handshake)
413→  {
414→    // In the server-as-participant model, other clients connecting to the same server
415→    // are NOT direct peers of this client — the server is the only direct peer.
416→    // Do not raise PeerCandidate here; the server handles relaying sync between clients.
417→    _logger.LogInformation("Peer joined notification (informational only): PeerId={PeerId}", handshake.PeerId);
418→
419→    return Task.CompletedTask;
420→  }
421→
422→  /// <inheritdoc />
423→  Task IDocumentsHubClient.OnPeerLeft(string peerId)
424→  {
425→    try
426→    {
427→      _logger.LogInformation("Peer left: PeerId={PeerId}", peerId);
428→
429→      // Raise PeerDisconnected event to notify Repo
430→      // This will clean up synchronization state for the disconnected peer
431→      var peer = new PeerId(peerId);
432→      _ = Task.Run(() => RaisePeerDisconnected(peer));
433→    }
434→    catch (Exception ex)
435→    {
436→      _logger.LogError(ex, "Error processing peer left notification for {PeerId}", peerId);
437→    }
438→
439→    return Task.CompletedTask;
440→  }
441→
442→  IRepoMessage? DeserializeMessage(MessageDto messageDto)
443→  {
444→    var senderId = new PeerId(messageDto.SenderId);
445→
446→    DocumentId RequireDocumentId(string? value)
447→    {
448→      if(string.IsNullOrWhiteSpace(value))
449→      {
450→        _logger.LogWarning("Received {MessageType} message without a document ID", messageDto.MessageType);
451→        throw new InvalidOperationException($"Message type {messageDto.MessageType} missing document ID");
452→      }
453→
454→      return DocumentId.Parse(value);
455→    }
456→
457→    return messageDto.MessageType switch
458→    {
459→      "sync" => new SyncMessage
460→      {
461→        DocumentId = RequireDocumentId(messageDto.DocumentId),
462→        Data = messageDto.Data,
463→        SenderId = senderId
464→      },
465→      "request" => new RequestMessage
466→      {
467→        DocumentId = RequireDocumentId(messageDto.DocumentId),
468→        Data = messageDto.Data,
469→        SenderId = senderId
470→      },
471→      // Note: Ephemeral messages require additional fields (Count, SessionId) that aren't in MessageDto
472→      // These would need to be encoded in the Data field and deserialized here
473→      // For now, we log a warning and skip these messages
474→      "ephemeral" => LogUnsupportedMessage("ephemeral"),
475→      "doc-unavailable" => new DocumentUnavailableMessage
476→      {
477→        DocumentId = RequireDocumentId(messageDto.DocumentId),
478→        SenderId = senderId
479→      },
480→      "doc-snapshot" => new DocumentSnapshotMessage
481→      {
482→        DocumentId = RequireDocumentId(messageDto.DocumentId),
483→        Data = messageDto.Data ?? Array.Empty<byte>(),
484→        SenderId = senderId
485→      },
486→      // Note: RemoteHeadsChangedMessage requires NewHeads which isn't in MessageDto
487→      "remote-heads-changed" => LogUnsupportedMessage("remote-heads-changed"),
488→      // Note: RemoteSubscriptionChangeMessage has readonly DocumentId
489→      "remote-subscription-change" => LogUnsupportedMessage("remote-subscription-change"),
490→      _ => null
491→    };
492→  }
493→
494→  IRepoMessage? LogUnsupportedMessage(string messageType)
495→  {
496→    _logger.LogWarning("Message type {MessageType} is not yet fully supported in wire protocol", messageType);
497→    return null;
498→  }
499→
500→  Task OnConnectionClosedAsync(Exception? exception)
501→  {
502→    _logger.LogWarning(exception, "SignalR connection closed");
503→
504→    _isReady = false;
505→
506→    if (_peerId is not null)
507→      RaisePeerDisconnected(_peerId.Value);
508→
509→    RaiseClosed();
510→
511→    return Task.CompletedTask;
512→  }
513→
514→  void RaisePeerCandidate(PeerId peerId, PeerMetadata? metadata)
515→  {
516→    try
517→    {
518→      PeerCandidate?.Invoke(this, new PeerCandidateEventArgs
519→      {
520→        PeerId = peerId,
521→        Metadata = metadata
522→      });
523→    }
524→    catch (Exception ex)
525→    {
526→      _logger.LogError(ex, "Error raising PeerCandidate event");
527→    }
528→  }
529→
530→  void RaisePeerDisconnected(PeerId peerId)
531→  {
532→    try
533→    {
534→      PeerDisconnected?.Invoke(this, new PeerDisconnectedEventArgs
535→      {
536→        PeerId = peerId
537→      });
538→    }
539→    catch (Exception ex)
540→    {
541→      _logger.LogError(ex, "Error raising PeerDisconnected event");
542→    }
543→  }
544→
545→  void RaiseMessageReceived(IRepoMessage message)
546→  {
547→    try
548→    {
549→      MessageReceived?.Invoke(this, new MessageReceivedEventArgs
550→      {
551→        Message = message
552→      });
553→    }
554→    catch (Exception ex)
555→    {
556→      _logger.LogError(ex, "Error raising MessageReceived event");
557→    }
558→  }
559→
560→  static byte[]? GetMessageData(IRepoMessage message)
561→  {
562→    return message switch
563→    {
564→      SyncMessage sync => sync.Data,
565→      RequestMessage request => request.Data,
566→      EphemeralMessage ephemeral => ephemeral.Data,
567→      DocumentUnavailableMessage _ => Array.Empty<byte>(),
568→      DocumentSnapshotMessage snapshot => snapshot.Data,
569→      _ => null
570→    };
571→  }
572→
573→  static IRepoMessage EnsureSender(IRepoMessage message, PeerId senderId)
574→  {
575→    if (message.SenderId is not null)
576→      return message;
577→
578→    return message switch
579→    {
580→      SyncMessage sync => sync with { SenderId = senderId },
581→      RequestMessage request => request with { SenderId = senderId },
582→      EphemeralMessage ephemeral => ephemeral with { SenderId = senderId },
583→      DocumentUnavailableMessage unavailable => unavailable with { SenderId = senderId },
584→      RemoteHeadsChangedMessage heads => heads with { SenderId = senderId },
585→      RemoteSubscriptionChangeMessage subscription => subscription with { SenderId = senderId },
586→      _ => message
587→    };
588→  }
589→
590→  void RaiseClosed()
591→  {
592→    try
593→    {
594→      Closed?.Invoke(this, EventArgs.Empty);
595→    }
596→    catch (Exception ex)
597→    {
598→      _logger.LogError(ex, "Error raising Closed event");
599→    }
600→  }
601→
602→  /// <inheritdoc />
603→  public void Dispose()
604→  {
605→    DisposeAsync().AsTask().GetAwaiter().GetResult();
606→  }
607→
608→  /// <inheritdoc />
609→  public async ValueTask DisposeAsync()
610→  {
611→    if (_disposed)
612→      return;
613→
614→    _disposed = true;
615→
616→    await Disconnect();
617→    _lock.Dispose();
618→  }
619→}
