  3→using Microsoft.AspNetCore.SignalR.Client;
  4→using Microsoft.Extensions.DependencyInjection;
  5→using Microsoft.Extensions.Logging;
  6→using Microsoft.Extensions.Options;
  7→
  8→// ReSharper disable ClassNeverInstantiated.Global
  9→namespace Six.Automerge.Repo.Network.SignalR.Client;
 10→
 11→/// <summary>
 12→/// <para>
 13→/// SignalRConnectionService is a service that provides simple way to connect to a SignalR hub from the client apps
 14→/// and take care of the connection lifecycle.
 15→/// </para>
 16→/// <para>
 17→/// It reuses existing connection if it's already created to avoid unecessary connections (which should be avoided).
 18→/// The best practice is to create a single connection for a SignalR hub and reuse it across the application.
 19→/// </para>
 20→/// <para>
 21→/// It also supports keyed services, so you can have multiple SignalR hubs (and connections to them)
 22→/// in the same application. See more how it works in the SignalRConnectionServiceExtensions class.
 23→/// </para>
 24→/// <para>
 25→/// For example, when you want to inject the (keyed) SignalR connection
 26→/// service into another service that depends on it:
 27→/// <c>
 28→/// [FromKeyedServices("DocumentHub")] ISignalRConnectionService connectionService
 29→/// </c>
 30→/// </para>
 31→/// </summary>
 32→[PublicAPI]
 33→[ExcludeFromCodeCoverage]
 34→public class SignalRConnectionService : ISignalRConnectionService
 35→{
 36→  readonly ILogger _logger;
 37→  readonly ILoggerFactory _loggerFactory;
 38→  readonly SignalRConnectionServiceOptions _options;
 39→  HubConnection? _connection;
 40→
 41→  public SignalRConnectionService(ILoggerFactory loggerFactory, IOptionsMonitor<SignalRConnectionServiceOptions> options, string name)
 42→  {
 43→    _options = options.Get(name);
 44→    _loggerFactory = loggerFactory;
 45→    _logger = loggerFactory.CreateLogger<SignalRConnectionService>();
 46→  }
 47→
 48→  public async Task<HubConnection> GetConnection()
 49→  {
 50→    if(_connection is null)
 51→    {
 52→      _logger.LogInformation("Creating SignalR connection to: {Url}", _options.HubUrl);
 53→
 54→      var builder = new HubConnectionBuilder()
 55→        .WithUrl(_options.HubUrl);
 56→
 57→      if(_options.UseMessagePackProtocol)
 58→      {
 59→        builder.AddMessagePackProtocol(options =>
 60→        {
 61→          // Use LZ4 compression for MessagePack (this reduces the size of messages even further)
 62→          options.SerializerOptions =
 63→            MessagePackSerializerOptions.Standard.WithCompression(MessagePackCompression.Lz4Block);
 64→        });
 65→      }
 66→      else
 67→      {
 68→        builder.AddJsonProtocol(options =>
 69→        {
 70→          // Ignore null values in DTOs when writing JSON
 71→          options.PayloadSerializerOptions.DefaultIgnoreCondition = JsonIgnoreCondition.WhenWritingNull;
 72→        });
 73→      }
 74→
 75→      if(_options.EnableAutomaticReconnect)
 76→        builder = builder.WithAutomaticReconnect();
 77→
 78→      try
 79→      {
 80→        _connection = builder.Build();
 81→        _logger.LogInformation("SignalR connection to: {Url} created successfully", _options.HubUrl);
 82→      }
 83→      catch(Exception ex)
 84→      {
 85→        _logger.LogError("Failed to create a SignalR connection: {Url}. Failed with error: {Error}", _options.HubUrl,
 86→          ex.Message);
 87→      }
 88→    }
 89→
 90→    await Start();
 91→
 92→    return _connection ??
 93→           throw new NullReferenceException($"SignalR connection to: {_options.HubUrl} is null reference");
 94→  }
 95→
 96→  public async Task Start()
 97→  {
 98→    if(_connection is not null && _options.AutoStart && _connection.State == HubConnectionState.Disconnected)
 99→    {
100→      _logger.LogInformation("Starting SignalR connection to: {Url}", _options.HubUrl);
101→      await _connection.StartAsync();
102→    }
103→  }
104→
105→  public async Task Stop()
106→  {
107→    if(_connection is not null && _connection.State is HubConnectionState.Connected)
108→    {
109→      _logger.LogInformation("Stopping SignalR connection to: {Url}", _options.HubUrl);
110→      await _connection.StopAsync();
111→    }
112→  }
113→
114→  public void Dispose()
115→  {
116→    DisposeAsync().GetAwaiter().GetResult();
117→  }
118→
119→  public async ValueTask DisposeAsync()
120→  {
121→    if(_connection is not null)
122→    {
123→      await _connection.DisposeAsync();
124→      _connection = null;
125→    }
126→  }
127→}

