  3→using Six.Automerge.Repository;
  4→
  5→namespace Six.Automerge.TextEdit;
  6→
  7→/// <summary>
  8→/// High-level wrapper around an Automerge text CRDT that provides
  9→/// cached text/formatting state, debounced change application,
 10→/// and events for text and formatting changes.
 11→/// </summary>
 12→[PublicAPI]
 13→public sealed class TextDocument : IDisposable
 14→{
 15→  readonly DocHandle<object> _handle;
 16→  readonly TextDocumentOptions _options;
 17→  readonly AutomergeObjectId _textObjectId;
 18→  readonly SemaphoreSlim _refreshLock = new(1, 1);
 19→
 20→  ChangeDebouncer? _debouncer;
 21→  string _cachedText = string.Empty;
 22→  FormattedText _cachedFormattedText = new([]);
 23→  bool _isLocalChange;
 24→  bool _isDisposed;
 25→
 26→  public event EventHandler<TextChangedEventArgs>? TextChanged;
 27→  public event EventHandler<FormattedTextChangedEventArgs>? FormattedTextChanged;
 28→
 29→  /// <summary>
 30→  /// Gets the current plain text content.
 31→  /// </summary>
 32→  public string Text => Volatile.Read(ref _cachedText);
 33→
 34→  /// <summary>
 35→  /// Gets the current formatted text content.
 36→  /// </summary>
 37→  public FormattedText FormattedText => Volatile.Read(ref _cachedFormattedText);
 38→
 39→  /// <summary>
 40→  /// Gets the underlying document handle.
 41→  /// </summary>
 42→  public DocHandle<object> Handle => _handle;
 43→
 44→  /// <summary>
 45→  /// Gets the document ID.
 46→  /// </summary>
 47→  public string DocumentId => _handle.DocumentId;
 48→
 49→  internal TextDocument(DocHandle<object> handle, AutomergeObjectId textObjectId, TextDocumentOptions options)
 50→  {
 51→    ArgumentNullException.ThrowIfNull(handle);
 52→    ArgumentNullException.ThrowIfNull(textObjectId);
 53→    ArgumentNullException.ThrowIfNull(options);
 54→
 55→    _handle = handle;
 56→    _textObjectId = textObjectId;
 57→    _options = options;
 58→  }
 59→
 60→  /// <summary>
 61→  /// Creates a new document with a text field and returns a wired <see cref="TextDocument"/>.
 62→  /// </summary>
 63→  /// <param name="repo">The repository to create the document in.</param>
 64→  /// <param name="options">Options controlling the text field key, debounce, and sync settings.</param>
 65→  /// <param name="cancellationToken">Cancellation token.</param>
 66→  /// <returns>A fully initialized <see cref="TextDocument"/>.</returns>
 67→  public static async Task<TextDocument> CreateAsync(
 68→    Repository.Repo repo,
 69→    TextDocumentOptions? options = null,
 70→    CancellationToken cancellationToken = default)
 71→  {
 72→    ArgumentNullException.ThrowIfNull(repo);
 73→    options ??= new TextDocumentOptions();
 74→
 75→    var handle = await repo.Create<object>().ConfigureAwait(false);
 76→
 77→    AutomergeObjectId textObjectId = default!;
 78→    await handle.ChangeAsync(
 79→      doc =>
 80→      {
 81→        textObjectId = doc.PutObject(doc.RootId, options.TextFieldKey, AutomergeContainerType.Text);
 82→      },
 83→      cancellationToken: cancellationToken).ConfigureAwait(false);
 84→
 85→    var textDoc = new TextDocument(handle, textObjectId, options);
 86→    await textDoc.InitializeAsync(cancellationToken).ConfigureAwait(false);
 87→    return textDoc;
 88→  }
 89→
 90→  /// <summary>
 91→  /// Opens an existing document, waits for it to be ready, and returns a wired <see cref="TextDocument"/>.
 92→  /// Returns null if the document is not found within the timeout period.
 93→  /// </summary>
 94→  /// <param name="repo">The repository containing the document.</param>
 95→  /// <param name="documentId">The ID of the document to open.</param>
 96→  /// <param name="options">Options controlling the text field key, debounce, and sync settings.</param>
 97→  /// <param name="timeout">Timeout for finding the document. Default: 10 seconds.</param>
 98→  /// <param name="cancellationToken">Cancellation token.</param>
 99→  /// <returns>
100→  /// A fully initialized <see cref="TextDocument"/>, or null if the document was not found.
101→  /// </returns>
102→  public static async Task<TextDocument?> OpenAsync(
103→    Repository.Repo repo,
104→    string documentId,
105→    TextDocumentOptions? options = null,
106→    TimeSpan? timeout = null,
107→    CancellationToken cancellationToken = default)
108→  {
109→    ArgumentNullException.ThrowIfNull(repo);
110→    ArgumentException.ThrowIfNullOrWhiteSpace(documentId);
111→    options ??= new TextDocumentOptions();
112→
113→    var handle = await repo.Find<object>(documentId, timeout).ConfigureAwait(false);
114→    if(handle is null)
115→    {
116→      return null;
117→    }
118→
119→    var textObjectId = await handle.ReadAsync(
120→      doc => doc.GetObject(doc.RootId, options.TextFieldKey),
121→      cancellationToken).ConfigureAwait(false);
122→
123→    if(textObjectId is null)
124→    {
125→      return null;
126→    }
127→
128→    var textDoc = new TextDocument(handle, textObjectId, options);
129→    await textDoc.InitializeAsync(cancellationToken).ConfigureAwait(false);
130→    return textDoc;
131→  }
132→
133→  /// <summary>
134→  /// Initializes the document by reading the current text and spans
135→  /// from the DocHandle and subscribing to change events.
136→  /// </summary>
137→  internal async Task InitializeAsync(CancellationToken cancellationToken = default)
138→  {
139→    await RefreshFromDocumentAsync(cancellationToken).ConfigureAwait(false);
140→    _handle.Changed += OnDocHandleChanged;
141→  }
142→
143→  /// <summary>
144→  /// Applies a text change by diffing the new text against the cached text,
145→  /// computing a splice, and applying it to the document through the debouncer.
146→  /// </summary>
147→  public async Task ApplyTextChangeAsync(string newText, CancellationToken cancellationToken = default)
148→  {
149→    EnsureNotDisposed();
150→
151→    _debouncer ??= new ChangeDebouncer(
152→      TimeSpan.FromMilliseconds(_options.ChangeDebounceMs),
153→      FlushTextChangeAsync);
154→
155→    _debouncer.Schedule(newText);
156→  }
157→
158→  /// <summary>
159→  /// Applies a mark to a range of text.
160→  /// </summary>
161→  public async Task ApplyMarkAsync(
162→    ulong start,
163→    ulong end,
164→    string markName,
165→    string markValue,
166→    ExpandMode expand = ExpandMode.After,
167→    CancellationToken cancellationToken = default)
168→  {
169→    EnsureNotDisposed();
170→
171→    // Flush any pending text changes first
172→    if(_debouncer is not null)
173→    {
174→      await _debouncer.FlushAsync().ConfigureAwait(false);
175→    }
176→
177→    _isLocalChange = true;
178→    try
179→    {
180→      await _handle.ChangeAsync(
181→        doc => doc.Mark(_textObjectId, start, end, markName, markValue, expand),
182→        cancellationToken: cancellationToken).ConfigureAwait(false);
183→    }
184→    finally
185→    {
186→      _isLocalChange = false;
187→    }
188→
189→    await RefreshFromDocumentAsync(cancellationToken).ConfigureAwait(false);
190→    FormattedTextChanged?.Invoke(this, new FormattedTextChangedEventArgs(_cachedFormattedText, true));
191→  }
192→
193→  /// <summary>
194→  /// Applies a boolean mark to a range of text.
195→  /// </summary>
196→  public async Task ApplyMarkAsync(
197→    ulong start,
198→    ulong end,
199→    string markName,
200→    bool markValue,
201→    ExpandMode expand = ExpandMode.After,
202→    CancellationToken cancellationToken = default)
203→  {
204→    EnsureNotDisposed();
205→
206→    if(_debouncer is not null)
207→    {
208→      await _debouncer.FlushAsync().ConfigureAwait(false);
209→    }
210→
211→    _isLocalChange = true;
212→    try
213→    {
214→      await _handle.ChangeAsync(
215→        doc => doc.Mark(_textObjectId, start, end, markName, markValue, expand),
216→        cancellationToken: cancellationToken).ConfigureAwait(false);
217→    }
218→    finally
219→    {
220→      _isLocalChange = false;
221→    }
222→
223→    await RefreshFromDocumentAsync(cancellationToken).ConfigureAwait(false);
224→    FormattedTextChanged?.Invoke(this, new FormattedTextChangedEventArgs(_cachedFormattedText, true));
225→  }
226→
227→  /// <summary>
228→  /// Removes a mark from a range of text.
229→  /// </summary>
230→  public async Task RemoveMarkAsync(
231→    string markName,
232→    ulong start,
233→    ulong end,
234→    ExpandMode expand = ExpandMode.After,
235→    CancellationToken cancellationToken = default)
236→  {
237→    EnsureNotDisposed();
238→
239→    if(_debouncer is not null)
240→    {
241→      await _debouncer.FlushAsync().ConfigureAwait(false);
242→    }
243→
244→    _isLocalChange = true;
245→    try
246→    {
247→      await _handle.ChangeAsync(
248→        doc => doc.Unmark(_textObjectId, markName, start, end, expand),
249→        cancellationToken: cancellationToken).ConfigureAwait(false);
250→    }
251→    finally
252→    {
253→      _isLocalChange = false;
254→    }
255→
256→    await RefreshFromDocumentAsync(cancellationToken).ConfigureAwait(false);
257→    FormattedTextChanged?.Invoke(this, new FormattedTextChangedEventArgs(_cachedFormattedText, true));
258→  }
259→
260→  public void Dispose()
261→  {
262→    if(_isDisposed)
263→    {
264→      return;
265→    }
266→
267→    _isDisposed = true;
268→
269→    if(_options.AutoFlushOnDispose && _debouncer is not null)
270→    {
271→      // Best-effort flush — fire and forget since Dispose is synchronous
272→      try
273→      {
274→        _debouncer.FlushAsync().GetAwaiter().GetResult();
275→      }
276→      catch(ObjectDisposedException)
277→      {
278→        // Handle already disposed
279→      }
280→    }
281→
282→    _handle.Changed -= OnDocHandleChanged;
283→    _debouncer?.Dispose();
284→    _refreshLock.Dispose();
285→  }
286→
287→  async Task FlushTextChangeAsync(string newText)
288→  {
289→    string currentText = _cachedText;
290→    var splice = TextDiff.ComputeSplice(currentText, newText);
291→
292→    if(!splice.HasChanges)
293→    {
294→      return;
295→    }
296→
297→    _isLocalChange = true;
298→    try
299→    {
300→      await _handle.ChangeAsync(
301→        doc => doc.SpliceText(
302→          _textObjectId,
303→          (ulong)splice.Offset,
304→          splice.DeleteCount,
305→          splice.InsertText)).ConfigureAwait(false);
306→    }
307→    finally
308→    {
309→      _isLocalChange = false;
310→    }
311→
312→    await RefreshFromDocumentAsync(CancellationToken.None).ConfigureAwait(false);
313→    TextChanged?.Invoke(this, new TextChangedEventArgs(_cachedText, true));
314→  }
315→
316→  void OnDocHandleChanged(object? sender, DocHandleChangeEventArgs<object> e)
317→  {
318→    if(_isDisposed || _isLocalChange)
319→    {
320→      return;
321→    }
322→
323→    _ = HandleRemoteChangeAsync();
324→  }
325→
326→  async Task HandleRemoteChangeAsync()
327→  {
328→    try
329→    {
330→      await RefreshFromDocumentAsync(CancellationToken.None).ConfigureAwait(false);
331→      TextChanged?.Invoke(this, new TextChangedEventArgs(_cachedText, false));
332→      FormattedTextChanged?.Invoke(this, new FormattedTextChangedEventArgs(_cachedFormattedText, false));
333→    }
334→    catch(ObjectDisposedException)
335→    {
336→      // Handle was disposed during async operation
337→    }
338→  }
339→
340→  async Task RefreshFromDocumentAsync(CancellationToken cancellationToken)
341→  {
342→    await _refreshLock.WaitAsync(cancellationToken).ConfigureAwait(false);
343→    try
344→    {
345→      var textId = _textObjectId;
346→
347→      var (text, spans) = await _handle.ReadAsync(
348→        doc =>
349→        {
350→          string t = doc.GetText(textId);
351→          var s = doc.GetSpans(textId);
352→          return (t, s);
353→        },
354→        cancellationToken).ConfigureAwait(false);
355→
356→      Volatile.Write(ref _cachedText, text);
357→      Volatile.Write(ref _cachedFormattedText, FormattedText.FromSpans(spans));
358→    }
359→    finally
360→    {
361→      _refreshLock.Release();
362→    }
363→  }
364→
365→  void EnsureNotDisposed()
366→  {
367→    ObjectDisposedException.ThrowIf(_isDisposed, this);
368→  }
369→}
