 1→using MessagePack;
 2→using MessagePack.Resolvers;
 3→using Server.Api.Hubs;
 4→
 5→var builder = WebApplication.CreateBuilder(args);
 6→
 7→// Add service defaults (includes service discovery, health checks, etc.)
 8→builder.AddServiceDefaults();
 9→
10→// Add SignalR with MessagePack (LZ4 compression) + JSON protocols
11→builder.Services
12→  .AddSignalR()
13→  .AddMessagePackProtocol(options =>
14→  {
15→    options.SerializerOptions = MessagePackSerializerOptions.Standard
16→      .WithCompression(MessagePackCompression.Lz4Block)
17→      .WithResolver(ContractlessStandardResolver.Instance);
18→  })
19→  .AddJsonProtocol();
20→
21→// Register SyncServer infrastructure (transport, sync server, hosted service)
22→builder.Services.AddSyncServer(options =>
23→{
24→  var envDir = Environment.GetEnvironmentVariable("SERVER_STORAGE_DIR");
25→  if(!string.IsNullOrWhiteSpace(envDir))
26→    options.StorageDirectory = envDir;
27→});
28→
29→builder.Services
30→  .AddCors(options =>
31→  {
32→    options.AddPolicy("AllowAll", policy =>
33→    {
34→      policy
35→        .SetIsOriginAllowed(_ => true)
36→        .AllowAnyMethod()
37→        .AllowAnyHeader()
38→        .AllowCredentials();
39→    });
40→  });
41→
42→if(builder.Environment.IsDevelopment())
43→{
44→  builder.Services.AddOpenApi();
45→}
46→
47→var app = builder.Build();
48→
49→app.UseHttpsRedirection();
50→app.UseCors("AllowAll");
51→
52→app.MapDefaultEndpoints();
53→
54→app.MapHub<DocumentsHub>("/hubs/documents");
55→
56→if(app.Environment.IsDevelopment())
57→{
58→  app.MapOpenApi();
59→}
60→
61→await app.RunAsync();
