 9→namespace Microsoft.Extensions.DependencyInjection;
10→
11→/// <summary>
12→/// Extension methods for registering SyncServer infrastructure in the DI container.
13→/// </summary>
14→[PublicAPI]
15→public static class ServerApiServiceCollectionExtensions
16→{
17→  /// <summary>
18→  /// Registers <see cref="SyncServer"/>, <see cref="SignalRServerTransport"/>,
19→  /// and the hosted service for graceful shutdown.
20→  /// </summary>
21→  /// <param name="services">The service collection.</param>
22→  /// <param name="configureStorage">
23→  /// Optional action to configure the storage directory.
24→  /// Defaults to <c>{AppContext.BaseDirectory}/documents</c>.
25→  /// </param>
26→  /// <returns>The service collection for chaining.</returns>
27→  public static IServiceCollection AddSyncServer(
28→    this IServiceCollection services,
29→    Action<SyncServerRegistrationOptions>? configureStorage = null)
30→  {
31→    ArgumentNullException.ThrowIfNull(services);
32→
33→    var registrationOptions = new SyncServerRegistrationOptions();
34→    configureStorage?.Invoke(registrationOptions);
35→
36→    // Register transport singleton
37→    services.AddSingleton<SignalRServerTransport>();
38→
39→    // Register SyncServer singleton
40→    services.AddSingleton(sp =>
41→    {
42→      var transport = sp.GetRequiredService<SignalRServerTransport>();
43→      var loggerFactory = sp.GetRequiredService<ILoggerFactory>();
44→
45→      var storageDir = registrationOptions.StorageDirectory;
46→      Directory.CreateDirectory(storageDir);
47→      var storage = new FileSystemStorageAdapter(storageDir);
48→
49→      var options = new SyncServerOptions
50→      {
51→        Storage = storage,
52→        PersistenceInterval = registrationOptions.PersistenceInterval,
53→        LoggerFactory = loggerFactory
54→      };
55→
56→      return new SyncServer(options, transport);
57→    });
58→
59→    // Register hosted service for graceful shutdown
60→    services.AddHostedService<SyncServerHostedService>();
61→
62→    return services;
63→  }
64→}
