70→public sealed class SyncServerRegistrationOptions
71→{
72→  /// <summary>
73→  /// Gets or sets the storage directory for documents.
74→  /// Defaults to <c>{AppContext.BaseDirectory}/documents</c>.
75→  /// </summary>
76→  public string StorageDirectory { get; set; } = Path.Combine(AppContext.BaseDirectory, "documents");
77→
78→  /// <summary>
79→  /// Gets or sets the interval between persistence flushes for dirty documents.
80→  /// Defaults to 5 seconds.
81→  /// </summary>
82→  public TimeSpan PersistenceInterval { get; set; } = TimeSpan.FromSeconds(5);
83→}
