 7→/// <summary>
 8→/// Hosted service that ensures <see cref="SyncServer"/> is shut down gracefully
 9→/// when the application stops. SyncServer is ready from construction, so
10→/// <see cref="StartAsync"/> is a no-op.
11→/// </summary>
12→sealed class SyncServerHostedService : IHostedService
13→{
14→  readonly SyncServer _syncServer;
15→
16→  public SyncServerHostedService(SyncServer syncServer)
17→  {
18→    _syncServer = syncServer;
19→  }
20→
21→  public Task StartAsync(CancellationToken cancellationToken) => Task.CompletedTask;
22→
23→  public async Task StopAsync(CancellationToken cancellationToken)
24→  {
25→    await _syncServer.DisposeAsync().ConfigureAwait(false);
26→  }
27→}
