  3→using Microsoft.AspNetCore.SignalR;
  4→using Six.Automerge.Repository;
  5→using Six.Automerge.Repository.Network;
  6→using Six.Automerge.Repository.Network.SignalR;
  7→using Six.Automerge.SyncServer;
  8→
  9→namespace Server.Api.Hubs;
 10→
 11→/// <summary>
 12→/// SignalR hub for Automerge document synchronization backed by <see cref="SyncServer"/>.
 13→/// All sync protocol messages are routed through the server's Repo, enabling the server
 14→/// to participate in document synchronization and persist documents.
 15→/// </summary>
 16→[PublicAPI]
 17→public sealed class DocumentsHub : Hub<IDocumentsHubClient>, IDocumentsHub
 18→{
 19→  readonly SyncServer _syncServer;
 20→  readonly SignalRServerTransport _transport;
 21→  readonly ILogger<DocumentsHub> _logger;
 22→
 23→  public DocumentsHub(
 24→    SyncServer syncServer,
 25→    SignalRServerTransport transport,
 26→    ILoggerFactory loggerFactory)
 27→  {
 28→    ArgumentNullException.ThrowIfNull(syncServer);
 29→    ArgumentNullException.ThrowIfNull(transport);
 30→    ArgumentNullException.ThrowIfNull(loggerFactory);
 31→
 32→    _syncServer = syncServer;
 33→    _transport = transport;
 34→    _logger = loggerFactory.CreateLogger<DocumentsHub>();
 35→  }
 36→
 37→  /// <inheritdoc />
 38→  public async Task<PeerHandshakeDto> Handshake(PeerHandshakeDto handshake)
 39→  {
 40→    try
 41→    {
 42→      _logger.LogInformation(
 43→        "Peer handshake: PeerId={PeerId}, ConnectionId={ConnectionId}",
 44→        handshake.PeerId, Context.ConnectionId);
 45→
 46→      Context.Items["PeerId"] = handshake.PeerId;
 47→
 48→      var peerId = new PeerId(handshake.PeerId);
 49→      var metadata = handshake.Metadata?.ToPeerMetadata();
 50→
 51→      _transport.RegisterPeer(Context.ConnectionId, peerId);
 52→      await _syncServer.OnPeerConnectedAsync(peerId, metadata);
 53→
 54→      await Clients.Others.OnPeerJoined(handshake);
 55→
 56→      return PeerHandshakeDto.Create(_syncServer.PeerId, null);
 57→    }
 58→    catch(Exception ex)
 59→    {
 60→      _logger.LogError(ex,
 61→        "Error during handshake. PeerId={PeerId}, ConnectionId={ConnectionId}",
 62→        handshake.PeerId, Context.ConnectionId);
 63→      throw;
 64→    }
 65→  }
 66→
 67→  /// <inheritdoc />
 68→  public async Task SendMessage(MessageDto message)
 69→  {
 70→    try
 71→    {
 72→      if(string.IsNullOrEmpty(message.DocumentId))
 73→      {
 74→        _logger.LogWarning(
 75→          "Received message with empty DocumentId. ConnectionId={ConnectionId}",
 76→          Context.ConnectionId);
 77→        return;
 78→      }
 79→
 80→      _logger.LogDebug(
 81→        "Routing message: DocumentId={DocumentId}, MessageType={MessageType}, SenderId={SenderId}",
 82→        message.DocumentId, message.MessageType, message.SenderId);
 83→
 84→      await Groups.AddToGroupAsync(Context.ConnectionId, message.DocumentId);
 85→
 86→      var repoMessage = DeserializeMessage(message);
 87→      if(repoMessage is not null)
 88→      {
 89→        var senderId = new PeerId(message.SenderId);
 90→        await _syncServer.OnMessageReceivedAsync(senderId, repoMessage);
 91→      }
 92→    }
 93→    catch(Exception ex)
 94→    {
 95→      _logger.LogError(ex,
 96→        "Error routing message. DocumentId={DocumentId}, ConnectionId={ConnectionId}",
 97→        message.DocumentId, Context.ConnectionId);
 98→    }
 99→  }
100→
101→  /// <inheritdoc />
102→  public async Task SubscribeToDocument(string documentId)
103→  {
104→    try
105→    {
106→      if(string.IsNullOrEmpty(documentId))
107→      {
108→        _logger.LogWarning("Subscribe with empty documentId. ConnectionId={ConnectionId}",
109→          Context.ConnectionId);
110→        return;
111→      }
112→
113→      await Groups.AddToGroupAsync(Context.ConnectionId, documentId);
114→
115→      _logger.LogInformation(
116→        "Client subscribed: DocumentId={DocumentId}, ConnectionId={ConnectionId}",
117→        documentId, Context.ConnectionId);
118→    }
119→    catch(Exception ex)
120→    {
121→      _logger.LogError(ex,
122→        "Error subscribing. DocumentId={DocumentId}, ConnectionId={ConnectionId}",
123→        documentId, Context.ConnectionId);
124→    }
125→  }
126→
127→  /// <inheritdoc />
128→  public async Task UnsubscribeFromDocument(string documentId)
129→  {
130→    try
131→    {
132→      if(string.IsNullOrEmpty(documentId))
133→      {
134→        _logger.LogWarning("Unsubscribe with empty documentId. ConnectionId={ConnectionId}",
135→          Context.ConnectionId);
136→        return;
137→      }
138→
139→      await Groups.RemoveFromGroupAsync(Context.ConnectionId, documentId);
140→
141→      _logger.LogInformation(
142→        "Client unsubscribed: DocumentId={DocumentId}, ConnectionId={ConnectionId}",
143→        documentId, Context.ConnectionId);
144→    }
145→    catch(Exception ex)
146→    {
147→      _logger.LogError(ex,
148→        "Error unsubscribing. DocumentId={DocumentId}, ConnectionId={ConnectionId}",
149→        documentId, Context.ConnectionId);
150→    }
151→  }
152→
153→  /// <summary>
154→  /// Returns the list of document IDs stored in the SyncServer.
155→  /// </summary>
156→  public async Task<List<string>> ListDocuments()
157→  {
158→    try
159→    {
160→      var docs = await _syncServer.ListDocumentsAsync();
161→      _logger.LogDebug("Listed {Count} documents", docs.Count);
162→      return docs.ToList();
163→    }
164→    catch(Exception ex)
165→    {
166→      _logger.LogError(ex, "Error listing documents");
167→      return [];
168→    }
169→  }
170→
171→  /// <inheritdoc />
172→  public override Task OnConnectedAsync()
173→  {
174→    _logger.LogInformation("Client connected: ConnectionId={ConnectionId}", Context.ConnectionId);
175→    return base.OnConnectedAsync();
176→  }
177→
178→  /// <inheritdoc />
179→  public override async Task OnDisconnectedAsync(Exception? exception)
180→  {
181→    var peerIdStr = Context.Items.TryGetValue("PeerId", out var id) ? id?.ToString() : null;
182→
183→    if(exception is not null)
184→    {
185→      _logger.LogWarning(exception,
186→        "Client disconnected with error: ConnectionId={ConnectionId}, PeerId={PeerId}",
187→        Context.ConnectionId, peerIdStr ?? "unknown");
188→    }
189→    else
190→    {
191→      _logger.LogInformation(
192→        "Client disconnected: ConnectionId={ConnectionId}, PeerId={PeerId}",
193→        Context.ConnectionId, peerIdStr ?? "unknown");
194→    }
195→
196→    if(!string.IsNullOrEmpty(peerIdStr))
197→    {
198→      var peerId = new PeerId(peerIdStr);
199→      _transport.UnregisterPeer(Context.ConnectionId);
200→      await _syncServer.OnPeerDisconnectedAsync(peerId);
201→      await Clients.Others.OnPeerLeft(peerIdStr);
202→    }
203→
204→    await base.OnDisconnectedAsync(exception);
205→  }
206→
207→  static IRepoMessage? DeserializeMessage(MessageDto messageDto)
208→  {
209→    var senderId = new PeerId(messageDto.SenderId);
210→
211→    return messageDto.MessageType switch
212→    {
213→      "sync" => new SyncMessage
214→      {
215→        DocumentId = DocumentId.Parse(messageDto.DocumentId!),
216→        Data = messageDto.Data,
217→        SenderId = senderId
218→      },
219→      "request" => new RequestMessage
220→      {
221→        DocumentId = DocumentId.Parse(messageDto.DocumentId!),
222→        Data = messageDto.Data,
223→        SenderId = senderId
224→      },
225→      "doc-unavailable" => new DocumentUnavailableMessage
226→      {
227→        DocumentId = DocumentId.Parse(messageDto.DocumentId!),
228→        SenderId = senderId
229→      },
230→      "doc-snapshot" => new DocumentSnapshotMessage
231→      {
232→        DocumentId = DocumentId.Parse(messageDto.DocumentId!),
233→        Data = messageDto.Data ?? [],
234→        SenderId = senderId
235→      },
236→      _ => null
237→    };
238→  }
239→}
