  3→using System.Collections.Concurrent;
  4→using Microsoft.AspNetCore.SignalR;
  5→using Six.Automerge.Repository;
  6→using Six.Automerge.Repository.Network;
  7→using Six.Automerge.Repository.Network.SignalR;
  8→using Six.Automerge.SyncServer;
  9→
 10→namespace Server.Api.Hubs;
 11→
 12→/// <summary>
 13→/// <see cref="IServerTransport"/> implementation backed by SignalR.
 14→/// Routes outgoing messages from <see cref="SyncServer"/> to connected clients
 15→/// via <see cref="IHubContext{THub,T}"/>.
 16→/// </summary>
 17→[PublicAPI]
 18→public sealed class SignalRServerTransport : IServerTransport, IDisposable
 19→{
 20→  readonly IHubContext<DocumentsHub, IDocumentsHubClient> _hubContext;
 21→  readonly ILogger<SignalRServerTransport> _logger;
 22→  readonly ConcurrentDictionary<string, PeerId> _connectionToPeer = new();
 23→  readonly ConcurrentDictionary<string, string> _peerToConnection = new(); // (string)PeerId → ConnectionId
 24→
 25→  bool _disposed;
 26→
 27→  public SignalRServerTransport(
 28→    IHubContext<DocumentsHub, IDocumentsHubClient> hubContext,
 29→    ILoggerFactory loggerFactory)
 30→  {
 31→    ArgumentNullException.ThrowIfNull(hubContext);
 32→    ArgumentNullException.ThrowIfNull(loggerFactory);
 33→
 34→    _hubContext = hubContext;
 35→    _logger = loggerFactory.CreateLogger<SignalRServerTransport>();
 36→  }
 37→
 38→  // Events required by IServerTransport but not raised in the hub-driven flow.
 39→  // The hub calls SyncServer methods directly rather than going through transport events.
 40→#pragma warning disable CS0067
 41→  public event EventHandler<ServerPeerConnectedEventArgs>? PeerConnected;
 42→  public event EventHandler<ServerPeerDisconnectedEventArgs>? PeerDisconnected;
 43→  public event EventHandler<ServerMessageReceivedEventArgs>? MessageReceived;
 44→#pragma warning restore CS0067
 45→
 46→  /// <inheritdoc />
 47→  public async Task SendAsync(PeerId peerId, IRepoMessage message)
 48→  {
 49→    if(_disposed) return;
 50→
 51→    if(!_peerToConnection.TryGetValue((string)peerId, out var connectionId))
 52→    {
 53→      _logger.LogDebug("SendAsync: No connection found for peer {PeerId}, dropping message", peerId);
 54→      return;
 55→    }
 56→
 57→    var dto = ToDto(message);
 58→    await _hubContext.Clients.Client(connectionId).OnReceiveMessage(dto).ConfigureAwait(false);
 59→
 60→    _logger.LogDebug(
 61→      "Sent {MessageType} to peer {PeerId} (connection {ConnectionId})",
 62→      message.MessageType, peerId, connectionId);
 63→  }
 64→
 65→  /// <inheritdoc />
 66→  public async Task BroadcastAsync(DocumentId documentId, IRepoMessage message)
 67→  {
 68→    if(_disposed) return;
 69→
 70→    var dto = ToDto(message);
 71→    await _hubContext.Clients.Group(documentId.Value).OnReceiveMessage(dto).ConfigureAwait(false);
 72→
 73→    _logger.LogDebug(
 74→      "Broadcast {MessageType} to group {DocumentId}",
 75→      message.MessageType, documentId.Value);
 76→  }
 77→
 78→  /// <summary>
 79→  /// Registers a peer-to-connection mapping so <see cref="SendAsync"/> can
 80→  /// target specific peers. Called by the hub on handshake.
 81→  /// </summary>
 82→  public void RegisterPeer(string connectionId, PeerId peerId)
 83→  {
 84→    _connectionToPeer[connectionId] = peerId;
 85→    _peerToConnection[(string)peerId] = connectionId;
 86→
 87→    _logger.LogInformation(
 88→      "Peer registered: PeerId={PeerId}, ConnectionId={ConnectionId}",
 89→      peerId, connectionId);
 90→  }
 91→
 92→  /// <summary>
 93→  /// Removes a peer-to-connection mapping. Called by the hub on disconnect.
 94→  /// </summary>
 95→  public void UnregisterPeer(string connectionId)
 96→  {
 97→    if(_connectionToPeer.TryRemove(connectionId, out var peerId))
 98→    {
 99→      _peerToConnection.TryRemove((string)peerId, out _);
100→
101→      _logger.LogInformation(
102→        "Peer unregistered: PeerId={PeerId}, ConnectionId={ConnectionId}",
103→        peerId, connectionId);
104→    }
105→  }
106→
107→  /// <summary>
108→  /// Looks up the peer ID for a given SignalR connection.
109→  /// </summary>
110→  public bool TryGetPeerId(string connectionId, out PeerId peerId)
111→  {
112→    if(_connectionToPeer.TryGetValue(connectionId, out var id))
113→    {
114→      peerId = id;
115→      return true;
116→    }
117→
118→    peerId = default;
119→    return false;
120→  }
121→
122→  /// <summary>
123→  /// Gets the number of currently connected peers.
124→  /// </summary>
125→  public int GetConnectedPeerCount() => _connectionToPeer.Count;
126→
127→  /// <inheritdoc />
128→  public void Dispose()
129→  {
130→    if(_disposed) return;
131→    _disposed = true;
132→
133→    _connectionToPeer.Clear();
134→    _peerToConnection.Clear();
135→  }
136→
137→  static MessageDto ToDto(IRepoMessage message)
138→  {
139→    var data = message switch
140→    {
141→      SyncMessage sync => sync.Data ?? [],
142→      RequestMessage request => request.Data ?? [],
143→      EphemeralMessage ephemeral => ephemeral.Data ?? [],
144→      DocumentSnapshotMessage snapshot => snapshot.Data,
145→      DocumentUnavailableMessage => Array.Empty<byte>(),
146→      _ => Array.Empty<byte>()
147→    };
148→
149→    return MessageDto.FromRepoMessage(message, data);
150→  }
151→}
