  4→using Microsoft.Extensions.Logging;
  5→using Microsoft.Extensions.Logging.Abstractions;
  6→using Microsoft.Extensions.Options;
  7→using Six.Automerge.Repo.Network.SignalR;
  8→using Six.Automerge.Repo.Network.SignalR.Client;
  9→using Six.Automerge.Repository;
 10→using Six.Automerge.Repository.Network;
 11→using Six.Automerge.Repository.Storage.FileSystem;
 12→
 13→namespace DemoApp.Shared;
 14→
 15→/// <summary>
 16→/// Lifecycle manager for Repo + SignalRNetworkAdapter + FileSystemStorageAdapter.
 17→/// Provides a single entry point for demo apps to set up collaborative document sync.
 18→/// </summary>
 19→[PublicAPI]
 20→public sealed class RepoService : IDisposable
 21→{
 22→  readonly RepoServiceOptions _options;
 23→  readonly ILoggerFactory _loggerFactory;
 24→  readonly ILogger<RepoService> _logger;
 25→
 26→  FileSystemStorageAdapter? _storage;
 27→  SignalRConnectionService? _connectionService;
 28→  SignalRNetworkAdapter? _networkAdapter;
 29→  Repo? _repo;
 30→  HubConnection? _hubConnection;
 31→  ConnectionState _connectionState = ConnectionState.Disconnected;
 32→  int _peerCount;
 33→  bool _disposed;
 34→
 35→  /// <summary>
 36→  /// Initializes a new instance of the <see cref="RepoService"/> class.
 37→  /// </summary>
 38→  /// <param name="options">Configuration options.</param>
 39→  /// <param name="loggerFactory">Optional logger factory. Uses <see cref="NullLoggerFactory"/> if null.</param>
 40→  public RepoService(RepoServiceOptions options, ILoggerFactory? loggerFactory = null)
 41→  {
 42→    ArgumentNullException.ThrowIfNull(options);
 43→    _options = options;
 44→    _loggerFactory = loggerFactory ?? NullLoggerFactory.Instance;
 45→    _logger = _loggerFactory.CreateLogger<RepoService>();
 46→  }
 47→
 48→  /// <summary>
 49→  /// Gets the peer ID of this repo instance. Null before initialization.
 50→  /// </summary>
 51→  public PeerId? PeerId => _repo?.PeerId;
 52→
 53→  /// <summary>
 54→  /// Gets the current connection state to the SignalR hub.
 55→  /// </summary>
 56→  public ConnectionState ConnectionState => _connectionState;
 57→
 58→  /// <summary>
 59→  /// Gets the number of currently connected peers.
 60→  /// </summary>
 61→  public int PeerCount => _peerCount;
 62→
 63→  /// <summary>
 64→  /// Gets the underlying <see cref="Repo"/> instance. Null before initialization.
 65→  /// </summary>
 66→  public Repo? Repo => _repo;
 67→
 68→  /// <summary>
 69→  /// Gets whether the service has been initialized.
 70→  /// </summary>
 71→  public bool IsInitialized => _repo is not null;
 72→
 73→  /// <summary>
 74→  /// Gets the underlying <see cref="Microsoft.AspNetCore.SignalR.Client.HubConnection"/>.
 75→  /// Null before initialization.
 76→  /// </summary>
 77→  public HubConnection? HubConnection => _hubConnection;
 78→
 79→  /// <summary>
 80→  /// Gets the resolved hub URL. If <see cref="RepoServiceOptions.HubUrl"/> is set, returns it directly.
 81→  /// Otherwise, resolves the base URL from Aspire service discovery env vars and appends
 82→  /// <see cref="RepoServiceOptions.HubPath"/>.
 83→  /// </summary>
 84→  public string ResolvedHubUrl =>
 85→    _options.HubUrl ?? $"{ResolveServerBaseUrl()}{_options.HubPath}";
 86→
 87→  /// <summary>
 88→  /// Gets the resolved storage directory path.
 89→  /// </summary>
 90→  public string StorageDirectory =>
 91→    _options.StorageBaseDir
 92→    ?? Path.Combine(
 93→      Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),
 94→      ".rayautomerge",
 95→      _options.AppName);
 96→
 97→  /// <summary>
 98→  /// Raised when the connection state changes.
 99→  /// </summary>
100→  public event EventHandler<ConnectionState>? ConnectionStateChanged;
101→
102→  /// <summary>
103→  /// Raised when the peer count changes.
104→  /// </summary>
105→  public event EventHandler<int>? PeerCountChanged;
106→
107→  /// <summary>
108→  /// Initializes the repo, storage, and network adapter.
109→  /// Creates the storage directory, connects to the SignalR hub, and starts the repo.
110→  /// </summary>
111→  /// <param name="cancellationToken">Optional token to cancel the initialization.</param>
112→  public async Task InitializeAsync(CancellationToken cancellationToken = default)
113→  {
114→    ThrowIfDisposed();
115→    cancellationToken.ThrowIfCancellationRequested();
116→
117→    if(_repo is not null)
118→    {
119→      _logger.LogWarning("RepoService is already initialized");
120→      return;
121→    }
122→
123→    string resolvedUrl = ResolvedHubUrl;
124→    _logger.LogInformation("Initializing RepoService for app '{AppName}' with hub URL: {HubUrl}", _options.AppName, resolvedUrl);
125→
126→    // Create file system storage
127→    string storageDir = StorageDirectory;
128→    Directory.CreateDirectory(storageDir);
129→    _storage = new FileSystemStorageAdapter(storageDir);
130→    _logger.LogInformation("Storage initialized at: {StorageDir}", storageDir);
131→
132→    cancellationToken.ThrowIfCancellationRequested();
133→
134→    // Create SignalR connection service
135→    IOptionsMonitor<SignalRConnectionServiceOptions> optionsMonitor =
136→      new StaticOptionsMonitor(new SignalRConnectionServiceOptions
137→      {
138→        HubUrl = resolvedUrl,
139→        AutoStart = true,
140→        EnableAutomaticReconnect = true,
141→        UseMessagePackProtocol = true
142→      });
143→
144→    _connectionService = new SignalRConnectionService(_loggerFactory, optionsMonitor, string.Empty);
145→
146→    // Create network adapter
147→    _networkAdapter = new SignalRNetworkAdapter(_connectionService, _loggerFactory);
148→
149→    // Create repo
150→    _repo = new Repo(new RepoConfig
151→    {
152→      Storage = _storage,
153→      NetworkAdapters = [_networkAdapter]
154→    });
155→
156→    _logger.LogInformation("Repo created with PeerId: {PeerId}", _repo.PeerId);
157→
158→    // Wire up peer events
159→    _repo.PeerConnected += OnPeerConnected;
160→    _repo.PeerDisconnected += OnPeerDisconnected;
161→
162→    // Connect the network adapter
163→    SetConnectionState(ConnectionState.Connecting);
164→
165→    try
166→    {
167→      _networkAdapter.Connect(_repo.PeerId);
168→      await _networkAdapter.WhenReady().WaitAsync(_options.ConnectionTimeout, cancellationToken);
169→
170→      // Capture the hub connection for RPC calls (e.g., ListServerDocumentsAsync)
171→      _hubConnection = await _connectionService.GetConnection();
172→
173→      SetConnectionState(ConnectionState.Connected);
174→      _logger.LogInformation("Connected to SignalR hub: {HubUrl}", resolvedUrl);
175→    }
176→    catch(OperationCanceledException) when(cancellationToken.IsCancellationRequested)
177→    {
178→      _logger.LogWarning("RepoService initialization was cancelled");
179→      SetConnectionState(ConnectionState.Disconnected);
180→      throw;
181→    }
182→    catch(Exception ex)
183→    {
184→      _logger.LogWarning(ex, "Failed to connect to SignalR hub: {HubUrl}. Repo will work offline.", resolvedUrl);
185→      SetConnectionState(ConnectionState.Disconnected);
186→    }
187→  }
