189→  /// <summary>
190→  /// Queries the server for the list of document IDs stored for this app's hub.
191→  /// Requires an active connection.
192→  /// </summary>
193→  /// <returns>A list of document ID strings.</returns>
194→  /// <exception cref="InvalidOperationException">Thrown when the service is not initialized or not connected.</exception>
195→  public async Task<List<string>> ListServerDocumentsAsync()
196→  {
197→    ThrowIfDisposed();
198→
199→    if(_hubConnection is null || _connectionState != ConnectionState.Connected)
200→      throw new InvalidOperationException("Cannot list server documents: not connected to hub.");
201→
202→    _logger.LogDebug("Requesting document list from server hub");
203→    return await _hubConnection.InvokeAsync<List<string>>("ListDocuments");
204→  }
205→
206→  void OnPeerConnected(object? sender, PeerEventArgs e)
207→  {
208→    int count = Interlocked.Increment(ref _peerCount);
209→    _logger.LogInformation("Peer connected: {PeerId}. Total peers: {PeerCount}", e.PeerId, count);
210→    PeerCountChanged?.Invoke(this, count);
211→  }
212→
213→  void OnPeerDisconnected(object? sender, PeerEventArgs e)
214→  {
215→    int count = Interlocked.Add(ref _peerCount, -1);
216→    if(count < 0)
217→    {
218→      Interlocked.Exchange(ref _peerCount, 0);
219→      count = 0;
220→    }
221→
222→    _logger.LogInformation("Peer disconnected: {PeerId}. Total peers: {PeerCount}", e.PeerId, count);
223→    PeerCountChanged?.Invoke(this, count);
224→  }
225→
226→  void SetConnectionState(ConnectionState state)
227→  {
228→    if(_connectionState == state)
229→      return;
230→
231→    _connectionState = state;
232→    _logger.LogInformation("Connection state changed to: {State}", state);
233→    ConnectionStateChanged?.Invoke(this, state);
234→  }
