263→  /// <summary>
264→  /// Resolves the server base URL from Aspire service discovery environment variables.
265→  /// Falls back to <c>https://localhost:5001</c> if no env vars are set.
266→  /// </summary>
267→  static string ResolveServerBaseUrl()
268→  {
269→    string? baseUrl = Environment.GetEnvironmentVariable("services__api__https__0")
270→      ?? Environment.GetEnvironmentVariable("services__api__http__0");
271→
272→    if(!string.IsNullOrEmpty(baseUrl))
273→    {
274→      return baseUrl.TrimEnd('/');
275→    }
276→
277→    // Fallback to HUB_BASE_URL env var or default
278→    string? hubBaseUrl = Environment.GetEnvironmentVariable("HUB_BASE_URL");
279→    if(!string.IsNullOrEmpty(hubBaseUrl))
280→    {
281→      return hubBaseUrl.TrimEnd('/');
282→    }
283→
284→    return "https://localhost:5001";
285→  }
