197→    var textId = await textDoc.Handle.ReadAsync(
198→      doc => doc.GetObject(doc.RootId, "content"));
199→    using AutomergeDocument forkedDoc = await textDoc.Handle.ReadAsync(doc => doc.Fork());
200→    forkedDoc.SpliceText(textId!, 5, 0, " World");
201→    forkedDoc.Commit("remote edit");
202→
203→    var underlyingDoc = ((IDocHandle)textDoc.Handle).GetDocument()!;
204→    underlyingDoc.Merge(forkedDoc);
205→    await textDoc.Handle.NotifyRemoteChangeAsync(underlyingDoc);
206→
207→    // Allow async event propagation
208→    await Task.Delay(100);
209→
210→    vm.DocumentText.Should().Be("Hello World");
211→  }
