  4→using Six.Automerge.Repository.Network;
  5→
  6→namespace Six.Automerge.SyncServer;
  7→
  8→/// <summary>
  9→/// An <see cref="INetworkAdapter"/> that bridges between the internal Repo and an
 10→/// <see cref="IServerTransport"/>. When the Repo sends a message, this adapter
 11→/// forwards it to the transport. When the transport raises events, this adapter
 12→/// relays them to the Repo via its own events.
 13→/// </summary>
 14→internal sealed class TransportBridgeAdapter : INetworkAdapter
 15→{
 16→  readonly IServerTransport _transport;
 17→  readonly PeerId _localPeerId;
 18→
 19→  public string AdapterId { get; }
 20→  public bool IsReady => true;
 21→
 22→  public event EventHandler<PeerCandidateEventArgs>? PeerCandidate;
 23→  public event EventHandler<PeerDisconnectedEventArgs>? PeerDisconnected;
 24→  public event EventHandler<MessageReceivedEventArgs>? MessageReceived;
 25→  public event EventHandler? Closed;
 26→
 27→  public TransportBridgeAdapter(IServerTransport transport, PeerId localPeerId)
 28→  {
 29→    _transport = transport ?? throw new ArgumentNullException(nameof(transport));
 30→    _localPeerId = localPeerId;
 31→    AdapterId = $"transport-bridge-{_localPeerId}";
 32→  }
 33→
 34→  public Task WhenReady() => Task.CompletedTask;
 35→
 36→  public void Connect(PeerId peerId, PeerMetadata? metadata = null)
 37→  {
 38→    // No-op — peer connections are driven by the transport events
 39→  }
 40→
 41→  /// <summary>
 42→  /// Called by the Repo when it wants to send a message. Routes to the transport.
 43→  /// </summary>
 44→  public void Send(IRepoMessage message)
 45→  {
 46→    if(message is null) throw new ArgumentNullException(nameof(message));
 47→
 48→    // Fire-and-forget: the transport's SendAsync/BroadcastAsync is async,
 49→    // but INetworkAdapter.Send is synchronous by design.
 50→    _ = SendViaTransportAsync(message);
 51→  }
 52→
 53→  async Task SendViaTransportAsync(IRepoMessage message)
 54→  {
 55→    try
 56→    {
 57→      if(message.TargetPeerId is { } targetPeerId)
 58→      {
 59→        await _transport.SendAsync(targetPeerId, message).ConfigureAwait(false);
 60→      }
 61→      else if(message.DocumentId is { } documentId)
 62→      {
 63→        await _transport.BroadcastAsync(documentId, message).ConfigureAwait(false);
 64→      }
 65→    }
 66→    catch(Exception)
 67→    {
 68→      // Transport errors should not crash the adapter
 69→    }
 70→  }
 71→
 72→  public Task Disconnect()
 73→  {
 74→    Closed?.Invoke(this, EventArgs.Empty);
 75→    return Task.CompletedTask;
 76→  }
 77→
 78→  /// <summary>
 79→  /// Injects a peer-connected event into the Repo's network subsystem.
 80→  /// </summary>
 81→  internal void RaisePeerConnected(PeerId peerId, PeerMetadata? metadata)
 82→  {
 83→    PeerCandidate?.Invoke(this, new PeerCandidateEventArgs { PeerId = peerId, Metadata = metadata });
 84→  }
 85→
 86→  /// <summary>
 87→  /// Injects a peer-disconnected event into the Repo's network subsystem.
 88→  /// </summary>
 89→  internal void RaisePeerDisconnected(PeerId peerId)
 90→  {
 91→    PeerDisconnected?.Invoke(this, new PeerDisconnectedEventArgs { PeerId = peerId });
 92→  }
 93→
 94→  /// <summary>
 95→  /// Injects a message-received event into the Repo's network subsystem.
 96→  /// </summary>
 97→  internal void RaiseMessageReceived(IRepoMessage message)
 98→  {
 99→    MessageReceived?.Invoke(this, new MessageReceivedEventArgs { Message = message });
100→  }
101→}
