// Copyright (c) Six. All rights reserved.

using System.Collections.Concurrent;
using Microsoft.AspNetCore.SignalR;
using Six.Automerge.Repository;
using Six.Automerge.Repository.Network;
using Six.Automerge.Repository.Network.SignalR;
using Six.Automerge.SyncServer;

namespace Server.Api.Hubs;

/// <summary>
/// <see cref="IServerTransport"/> implementation backed by SignalR.
/// Routes outgoing messages from <see cref="SyncServer"/> to connected clients
/// via <see cref="IHubContext{THub,T}"/>.
/// </summary>
[PublicAPI]
public sealed class SignalRServerTransport : IServerTransport, IDisposable
{
  readonly IHubContext<DocumentsHub, IDocumentsHubClient> _hubContext;
  readonly ILogger<SignalRServerTransport> _logger;
  readonly ConcurrentDictionary<string, PeerId> _connectionToPeer = new();
  readonly ConcurrentDictionary<string, string> _peerToConnection = new(); // (string)PeerId → ConnectionId

  bool _disposed;

  public SignalRServerTransport(
    IHubContext<DocumentsHub, IDocumentsHubClient> hubContext,
    ILoggerFactory loggerFactory)
  {
    ArgumentNullException.ThrowIfNull(hubContext);
    ArgumentNullException.ThrowIfNull(loggerFactory);

    _hubContext = hubContext;
    _logger = loggerFactory.CreateLogger<SignalRServerTransport>();
  }

  // Events required by IServerTransport but not raised in the hub-driven flow.
  // The hub calls SyncServer methods directly rather than going through transport events.
#pragma warning disable CS0067
  public event EventHandler<ServerPeerConnectedEventArgs>? PeerConnected;
  public event EventHandler<ServerPeerDisconnectedEventArgs>? PeerDisconnected;
  public event EventHandler<ServerMessageReceivedEventArgs>? MessageReceived;
#pragma warning restore CS0067

  /// <inheritdoc />
  public async Task SendAsync(PeerId peerId, IRepoMessage message)
  {
    if(_disposed) return;

    if(!_peerToConnection.TryGetValue((string)peerId, out var connectionId))
    {
      _logger.LogDebug("SendAsync: No connection found for peer {PeerId}, dropping message", peerId);
      return;
    }

    var dto = ToDto(message);
    await _hubContext.Clients.Client(connectionId).OnReceiveMessage(dto).ConfigureAwait(false);

    _logger.LogDebug(
      "Sent {MessageType} to peer {PeerId} (connection {ConnectionId})",
      message.MessageType, peerId, connectionId);
  }

  /// <inheritdoc />
  public async Task BroadcastAsync(DocumentId documentId, IRepoMessage message)
  {
    if(_disposed) return;

    var dto = ToDto(message);
    await _hubContext.Clients.Group(documentId.Value).OnReceiveMessage(dto).ConfigureAwait(false);

    _logger.LogDebug(
      "Broadcast {MessageType} to group {DocumentId}",
      message.MessageType, documentId.Value);
  }

  /// <summary>
  /// Registers a peer-to-connection mapping so <see cref="SendAsync"/> can
  /// target specific peers. Called by the hub on handshake.
  /// </summary>
  public void RegisterPeer(string connectionId, PeerId peerId)
  {
    _connectionToPeer[connectionId] = peerId;
    _peerToConnection[(string)peerId] = connectionId;

    _logger.LogInformation(
      "Peer registered: PeerId={PeerId}, ConnectionId={ConnectionId}",
      peerId, connectionId);
  }

  /// <summary>
  /// Removes a peer-to-connection mapping. Called by the hub on disconnect.
  /// </summary>
  public void UnregisterPeer(string connectionId)
  {
    if(_connectionToPeer.TryRemove(connectionId, out var peerId))
    {
      _peerToConnection.TryRemove((string)peerId, out _);

      _logger.LogInformation(
        "Peer unregistered: PeerId={PeerId}, ConnectionId={ConnectionId}",
        peerId, connectionId);
    }
  }

  /// <summary>
  /// Looks up the peer ID for a given SignalR connection.
  /// </summary>
  public bool TryGetPeerId(string connectionId, out PeerId peerId)
  {
    if(_connectionToPeer.TryGetValue(connectionId, out var id))
    {
      peerId = id;
      return true;
    }

    peerId = default;
    return false;
  }

  /// <summary>
  /// Gets the number of currently connected peers.
  /// </summary>
  public int GetConnectedPeerCount() => _connectionToPeer.Count;

  /// <inheritdoc />
  public void Dispose()
  {
    if(_disposed) return;
    _disposed = true;

    _connectionToPeer.Clear();
    _peerToConnection.Clear();
  }

  static MessageDto ToDto(IRepoMessage message)
  {
    var data = message switch
    {
      SyncMessage sync => sync.Data ?? [],
      RequestMessage request => request.Data ?? [],
      EphemeralMessage ephemeral => ephemeral.Data ?? [],
      DocumentSnapshotMessage snapshot => snapshot.Data,
      DocumentUnavailableMessage => Array.Empty<byte>(),
      _ => Array.Empty<byte>()
    };

    return MessageDto.FromRepoMessage(message, data);
  }
}

namespace Six.Automerge.Repository.Network.SignalR;

/// <summary>
/// Defines the server-side interface for the SignalR documents hub.
/// </summary>
/// <remarks>
/// This interface is implemented by the server hub to handle client-to-server RPC calls.
/// Clients invoke these methods to manage document subscriptions and send sync messages.
///
/// <para>
/// <strong>Document Groups:</strong><br/>
/// Each document has a corresponding SignalR group identified by its <c>DocumentId</c>.
/// Clients subscribe to groups to receive messages for specific documents.
/// The hub automatically routes messages to all group members except the sender.
/// </para>
///
/// <para>
/// <strong>Usage Example (Client Calling Hub):</strong>
/// <code>
/// var connection = new HubConnectionBuilder()
///   .WithUrl("https://server/hubs/documents")
///   .Build();
///
/// await connection.InvokeAsync("Handshake", new PeerHandshakeDto
/// {
///   PeerId = "peer-123",
///   Metadata = null
/// });
///
/// await connection.InvokeAsync("SubscribeToDocument", "doc-abc");
///
/// await connection.InvokeAsync("SendMessage", new MessageDto
/// {
///   MessageType = "sync",
///   DocumentId = "doc-abc",
///   SenderId = "peer-123",
///   Data = syncPayload
/// });
/// </code>
/// </para>
///
/// <para>
/// <strong>Usage Example (Server Hub Implementation):</strong>
/// <code>
/// public class DocumentsHub : Hub&lt;IDocumentsHubClient&gt;, IDocumentsHub
/// {
///   public async Task SendMessage(MessageDto message)
///   {
///     // Broadcast to all in group except sender
///     await Clients.OthersInGroup(message.DocumentId).OnReceiveMessage(message);
///   }
/// }
/// </code>
/// </para>
/// </remarks>
[PublicAPI]
public interface IDocumentsHub
{
  /// <summary>
  /// Establishes peer identity and metadata during connection.
  /// </summary>
  /// <param name="handshake">The handshake data containing peer ID and optional metadata.</param>
  /// <returns>A task representing the asynchronous operation.</returns>
  /// <remarks>
  /// This method should be called by the client immediately after connecting to the hub.
  /// The server uses the peer ID for tracking connections and preventing message echo-back.
  ///
  /// <para>
  /// Typical flow:
  /// <list type="number">
  ///   <item><description>Client connects to hub</description></item>
  ///   <item><description>Client calls <c>Handshake</c> with peer ID</description></item>
  ///   <item><description>Server logs connection and stores peer metadata</description></item>
  ///   <item><description>Client is ready to subscribe and send messages</description></item>
  /// </list>
  /// </para>
  /// </remarks>
  Task<PeerHandshakeDto> Handshake(PeerHandshakeDto handshake);

  /// <summary>
  /// Subscribes the calling peer to a document group to receive sync messages.
  /// </summary>
  /// <param name="documentId">The unique identifier of the document to subscribe to.</param>
  /// <returns>A task representing the asynchronous operation.</returns>
  /// <remarks>
  /// After subscribing, the client will receive all messages sent to this document via
  /// <see cref="IDocumentsHubClient.OnReceiveMessage"/>.
  ///
  /// <para>
  /// Subscriptions are automatically managed:
  /// <list type="bullet">
  ///   <item><description>Duplicate subscriptions are idempotent (no error)</description></item>
  ///   <item><description>Auto-subscribe occurs on first <see cref="SendMessage"/> if not already subscribed</description></item>
  ///   <item><description>All subscriptions are cleared on disconnect</description></item>
  /// </list>
  /// </para>
  /// </remarks>
  Task SubscribeToDocument(string documentId);

  /// <summary>
  /// Unsubscribes the calling peer from a document group.
  /// </summary>
  /// <param name="documentId">The unique identifier of the document to unsubscribe from.</param>
  /// <returns>A task representing the asynchronous operation.</returns>
  /// <remarks>
  /// After unsubscribing, the client will no longer receive messages for this document.
  /// Unsubscribing from a non-subscribed document is safe and does nothing.
  ///
  /// <para>
  /// Clients typically unsubscribe when:
  /// <list type="bullet">
  ///   <item><description>No longer editing a document</description></item>
  ///   <item><description>Reducing resource usage (memory, bandwidth)</description></item>
  ///   <item><description>Disconnecting gracefully (though automatic cleanup occurs on disconnect)</description></item>
  /// </list>
  /// </para>
  /// </remarks>
  Task UnsubscribeFromDocument(string documentId);

  /// <summary>
  /// Sends a sync message to all peers subscribed to the document.
  /// </summary>
  /// <param name="message">The message data transfer object containing the serialized repo message.</param>
  /// <returns>A task representing the asynchronous operation.</returns>
  /// <remarks>
  /// This is the primary method for Automerge document synchronization. The hub:
  ///
  /// <list type="number">
  ///   <item><description>Validates the message has a valid <see cref="MessageDto.DocumentId"/></description></item>
  ///   <item><description>Auto-subscribes the sender to the document group (if not already subscribed)</description></item>
  ///   <item><description>Broadcasts the message to all group members <strong>except the sender</strong></description></item>
  /// </list>
  ///
  /// <para>
  /// The message is sent to other peers via <see cref="IDocumentsHubClient.OnReceiveMessage"/>.
  /// The sender never receives their own message (SignalR's <c>OthersInGroup</c> behavior).
  /// </para>
  ///
  /// <para>
  /// <strong>Error Handling:</strong><br/>
  /// If <see cref="MessageDto.DocumentId"/> is null or empty, the message is logged and dropped.
  /// Serialization errors are logged but do not throw exceptions to avoid disrupting other clients.
  /// </para>
  /// </remarks>
  Task SendMessage(MessageDto message);
}

namespace Six.Automerge.Repository.Network.SignalR;

/// <summary>
/// Defines the client-side interface for SignalR hub callbacks.
/// </summary>
/// <remarks>
/// This interface is implemented by SignalR clients to receive messages from the server hub.
/// The server hub uses this interface via strongly-typed client proxies to invoke methods on connected clients.
///
/// <para>
/// <strong>Usage Example (Client Implementation):</strong>
/// <code>
/// public class MyAdapter : IDocumentsHubClient
/// {
///   public Task OnReceiveMessage(MessageDto message)
///   {
///     // Deserialize message.Data based on message.MessageType
///     // Raise MessageReceived event with IRepoMessage
///     return Task.CompletedTask;
///   }
/// }
/// </code>
/// </para>
///
/// <para>
/// <strong>Usage Example (Server Broadcasting):</strong>
/// <code>
/// // In DocumentsHub
/// await Clients.Group(documentId).OnReceiveMessage(messageDto);
/// </code>
/// </para>
/// </remarks>
[PublicAPI]
public interface IDocumentsHubClient
{
  /// <summary>
  /// Called by the server when a message is received for a document the client is subscribed to.
  /// </summary>
  /// <param name="message">The message data transfer object containing the serialized repo message.</param>
  /// <returns>A task representing the asynchronous operation.</returns>
  /// <remarks>
  /// This method is invoked by the SignalR hub when another peer sends a message to a document group
  /// that this client is subscribed to. The client should:
  ///
  /// <list type="number">
  ///   <item><description>Deserialize <see cref="MessageDto.Data"/> based on <see cref="MessageDto.MessageType"/></description></item>
  ///   <item><description>Reconstruct the appropriate <see cref="IRepoMessage"/> subtype</description></item>
  ///   <item><description>Raise the <c>MessageReceived</c> event for the network adapter</description></item>
  /// </list>
  ///
  /// The method should handle errors gracefully and return quickly to avoid blocking the SignalR pipeline.
  /// </remarks>
  Task OnReceiveMessage(MessageDto message);

  /// <summary>
  /// Called by the server when a new peer joins the network.
  /// </summary>
  /// <param name="handshake">The handshake information for the new peer.</param>
  /// <returns>A task representing the asynchronous operation.</returns>
  /// <remarks>
  /// This method is invoked by the SignalR hub when a new peer completes their handshake.
  /// The client should raise a <c>PeerCandidate</c> event to notify the Repo about the new peer,
  /// which will trigger document synchronization with the newly connected peer.
  /// </remarks>
  Task OnPeerJoined(PeerHandshakeDto handshake);

  /// <summary>
  /// Called by the server when a peer disconnects from the network.
  /// </summary>
  /// <param name="peerId">The ID of the peer that disconnected.</param>
  /// <returns>A task representing the asynchronous operation.</returns>
  /// <remarks>
  /// This method is invoked by the SignalR hub when a peer disconnects.
  /// The client should raise a <c>PeerDisconnected</c> event to notify the Repo,
  /// which will clean up synchronization state for the disconnected peer.
  /// </remarks>
  Task OnPeerLeft(string peerId);
}
